import { requireUser } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";

function esc(value: unknown) {
  return String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[char] ?? char));
}

function qrSvg(value: string) {
  const bits = Array.from({ length: 121 }, (_, index) => (value.charCodeAt(index % value.length) + index * 17) % 3 === 0);
  return `<svg width="116" height="116" viewBox="0 0 116 116" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="QR"><rect width="116" height="116" fill="#fff"/><rect x="4" y="4" width="28" height="28" fill="#123c8c"/><rect x="84" y="4" width="28" height="28" fill="#123c8c"/><rect x="4" y="84" width="28" height="28" fill="#123c8c"/>${bits.map((on, index) => on ? `<rect x="${40 + (index % 11) * 4}" y="${40 + Math.floor(index / 11) * 4}" width="4" height="4" fill="#123c8c"/>` : "").join("")}</svg>`;
}

export async function GET(_request: Request, { params }: { params: Promise<{ id: string }> }) {
  await requireUser();
  const { id } = await params;
  const requestUrl = new URL(_request.url);
  const supabase = await createClient();
  const [inspectionRes, answersRes, signatureRes, gpsRes, violationsRes, findingsRes, actionsRes] = await Promise.all([
    supabase.from("inspections" as any).select("*, gardens(name,city,address), inspectors:inspector_id(full_name, phone)").eq("id", id).single(),
    supabase.from("inspection_answers" as any).select("*, inspection_form_questions(question_text, category, weight, critical)").eq("inspection_id", id),
    supabase.from("inspection_signatures" as any).select("*").eq("inspection_id", id).order("signed_at", { ascending: false }).limit(1).maybeSingle(),
    supabase.from("inspection_gps_validations" as any).select("*").eq("inspection_id", id).order("created_at", { ascending: false }).limit(1).maybeSingle(),
    supabase.from("violations" as any).select("title,description,category,severity,status,correction_due_at,correction_note,correction_files").eq("inspection_id", id).order("created_at", { ascending: false }),
    supabase.from("national_compliance_findings" as any).select("title,description,severity,resolution_status,due_at,evidence").eq("inspection_id", id).order("created_at", { ascending: false }),
    supabase.from("inspection_follow_up_actions" as any).select("action_type,status,due_at,completed_at,notes,national_compliance_findings!inner(inspection_id,title)").eq("national_compliance_findings.inspection_id", id).order("created_at", { ascending: false })
  ]);
  const inspection = inspectionRes.data as any;
  if (inspectionRes.error || !inspection) {
    return new Response("לא ניתן לטעון את דוח הפיקוח או שאין הרשאה לצפות בו.", { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" } });
  }
  const answers = (answersRes.data ?? []) as any[];
  const signature = signatureRes.data as any;
  const gps = gpsRes.data as any;
  const violations = (violationsRes.data ?? []) as any[];
  const findings = (findingsRes.data ?? []) as any[];
  const actions = (actionsRes.data ?? []) as any[];
  const reportUrl = `${new URL(_request.url).origin}/dashboard/admin/inspections/${id}/report`;
  const documentNumber = `GB-INS-${new Date().getFullYear()}-${id.slice(0, 8).toUpperCase()}`;
  const verificationCode = Buffer.from(`${id}:${inspection?.weighted_score ?? ""}:${inspection?.completed_at ?? ""}`).toString("base64url").slice(0, 18).toUpperCase();
  const html = `<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><title>דוח ביקורת - ${esc(inspection?.gardens?.name)}</title><meta name="report-id" content="${esc(id)}"><meta name="document-number" content="${esc(documentNumber)}"><meta name="verification-code" content="${esc(verificationCode)}"><meta name="generated-at" content="${esc(new Date().toISOString())}"><style>@page{size:A4;margin:18mm;@bottom-center{content:"גן בטוח · ${esc(documentNumber)} · עמוד " counter(page) " מתוך " counter(pages);font-size:10px;color:#5b6680}}body{font-family:Arial,sans-serif;line-height:1.6;color:#14213d;background:#fff}.header{display:flex;justify-content:space-between;gap:24px;align-items:center;border-bottom:3px solid #22c69f;padding-bottom:18px}.brand{display:flex;align-items:center;gap:12px}.brand img{height:58px}.qr{border:1px solid #d9e3f0;border-radius:14px;padding:8px;text-align:center}.meta,.score-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.box{border:1px solid #d9e3f0;border-radius:14px;padding:12px;background:#f8fbff}.score{font-size:34px;color:#123c8c;font-weight:800}table{width:100%;border-collapse:collapse;margin-top:16px}td,th{border:1px solid #d9e3f0;padding:8px;vertical-align:top}th{background:#eaf6ff}.bad{color:#a3132b;font-weight:700}.sig{max-width:360px;border:1px solid #d9e3f0;border-radius:12px;padding:8px}.footer{margin-top:24px;border-top:1px solid #d9e3f0;padding-top:12px;color:#5b6680;font-size:12px}.evidence img{max-width:120px;max-height:90px;border-radius:8px;border:1px solid #ddd}.verification{font-family:monospace;direction:ltr;display:inline-block}</style></head><body><section class="header"><div class="brand"><img src="${new URL("/assets/company-symbol.png", _request.url)}" alt="גן בטוח"><div><h1>דוח ביקורת פיקוח</h1><p>${esc(inspection?.gardens?.name)} · ${esc(inspection?.gardens?.city)} · ${esc(inspection?.gardens?.address)}</p><p>מספר מסמך: <b>${esc(documentNumber)}</b> · קוד אימות: <b class="verification">${esc(verificationCode)}</b></p></div></div><div class="qr">${qrSvg(`${reportUrl}?verify=${verificationCode}`)}<small>QR אימות דוח</small></div></section><section class="meta"><div class="box">פקח<br><b>${esc(inspection?.inspectors?.full_name)}</b></div><div class="box">תאריך<br><b>${esc(inspection?.completed_at)}</b></div><div class="box">מזהה דוח<br><b>${esc(id)}</b></div><div class="box">נוצר<br><b>${esc(new Date().toLocaleString("he-IL"))}</b></div></section><section class="score-grid"><div class="box"><span>ציון סופי</span><div class="score">${esc(inspection?.weighted_score ?? "-")}</div></div><div class="box">ליקויים<br><b>${esc(inspection?.violation_count)}</b></div><div class="box">כשלים קריטיים<br><b>${esc(inspection?.critical_failures)}</b></div><div class="box">GPS<br><b>${esc(gps?.validation_result ?? "נבדק")}</b><br>${esc(signature?.gps_lat)}, ${esc(signature?.gps_lng)}</div></section><table><thead><tr><th>קטגוריה</th><th>שאלה</th><th>ציון</th><th>הערה</th><th>צילום/מסמך/וידאו</th></tr></thead><tbody>${answers.map((a) => `<tr><td>${esc(a.inspection_form_questions?.category)}</td><td>${esc(a.inspection_form_questions?.question_text)}</td><td class="${Number(a.score) <= 4 ? "bad" : ""}">${esc(a.score)}</td><td>${esc(a.note)}</td><td class="evidence">${a.photo_url ? `<a href="${esc(a.photo_url)}">צילום</a>` : ""} ${a.document_url ? `<a href="${esc(a.document_url)}">ראיה</a>` : ""} ${a.video_url ? `<a href="${esc(a.video_url)}">וידאו</a>` : ""}</td></tr>`).join("")}</tbody></table><h2>ממצאים ופעולות תיקון</h2><table><thead><tr><th>נושא</th><th>חומרה</th><th>סטטוס</th><th>יעד</th><th>הערה</th></tr></thead><tbody>${[...violations, ...findings].map((item) => `<tr><td>${esc(item.title)}</td><td>${esc(item.severity)}</td><td>${esc(item.status ?? item.resolution_status)}</td><td>${esc(item.correction_due_at ?? item.due_at ?? "")}</td><td>${esc(item.correction_note ?? item.description ?? "")}</td></tr>`).join("") || `<tr><td colspan="5">לא נרשמו ממצאים בדוח זה.</td></tr>`}</tbody></table><h2>מעקב תיקון</h2><table><thead><tr><th>פעולה</th><th>סטטוס</th><th>יעד</th><th>הערה</th></tr></thead><tbody>${actions.map((action) => `<tr><td>${esc(action.action_type)}</td><td>${esc(action.status)}</td><td>${esc(action.due_at)}</td><td>${esc(action.notes)}</td></tr>`).join("") || `<tr><td colspan="4">אין פעולות תיקון פתוחות.</td></tr>`}</tbody></table><h2>חתימת פקח</h2>${signature?.signature_image ? `<img class="sig" src="${esc(signature.signature_image)}">` : "<p>אין חתימה שמורה.</p>"}<p>נחתם: ${esc(signature?.signed_at)} · מרחק GPS: ${esc(gps?.distance_meters ?? signature?.gps_distance_meters)} מטר · נעילת מסמך: ${esc(inspection?.regulatory_locked_at ?? "")}</p><section class="footer">מסמך זה הופק ממערכת גן בטוח. הדוח אינו מהווה רישיון ממשלתי או ייעוץ משפטי, אלא תיעוד פיקוח פרטי וטכנולוגי לגני ילדים פרטיים. מטא־דאטה: document=${esc(documentNumber)}, verification=${esc(verificationCode)}, generated=${esc(new Date().toISOString())}.</section></body></html>`;
  const disposition = requestUrl.searchParams.get("download") === "1" ? "attachment" : "inline";
  const fileDate = new Date().toISOString().slice(0, 10);
  return new Response(html, { headers: { "Content-Type": "text/html; charset=utf-8", "Content-Disposition": `${disposition}; filename=gan-batuach-inspection-${fileDate}-${id.slice(0, 8)}.html` } });
}
